<script setup lang="ts">import { onMounted,ref } from 'vue';import { api } from '../../api/client';import AsyncState from '../../components/AsyncState.vue';const data=ref<any>(),error=ref(''),loading=ref(true);async function load(){loading.value=true;try{data.value=await api('/admin/system-health')}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}}onMounted(load)</script>
<template><section class="panel"><div class="panel-head"><div><h2>System health</h2><p>Migration, resource, policy, and write-boundary status.</p></div><button @click="load">Refresh</button></div><AsyncState :loading="loading" :error="error" :empty="!data"><pre>{{data}}</pre></AsyncState></section></template>
